from harness import *
srv=serve()
INIT="window.webkitSpeechRecognition=window.SpeechRecognition=function(){this.start=()=>{};this.stop=()=>{};this.abort=()=>{}};"
try:
  with sync_playwright() as p:
    b,pg,errs=newpage(p,touch=True,init=INIT,h=800)
    pg.route("**/dabsy-brain.swagatdemo9292.workers.dev**",lambda r:r.fulfill(status=500,body="{}"))
    pg.evaluate("""()=>{const D=window.DABSy;D.permissions.ensure=async()=>({granted:true});window.__listen=0;D.voice.startListening=()=>{window.__listen++};D.voice.stopListening=()=>{window.__stoppedL=(window.__stoppedL||0)+1};D.voice.stopSpeaking=()=>{window.__stopS=(window.__stopS||0)+1};D.voice.speak=()=>{};D.memory.getSettings().speakReplies=false}""")
    check("live talk button exists",pg.locator("#live-btn").count()==1)
    pg.evaluate("window.DABSy.app.openCommand()"); pg.wait_for_timeout(600)
    pg.click("#live-btn"); pg.wait_for_timeout(900)
    pg.evaluate("window.__tr=[];const bus=window.DABSy.bus,o=bus.emit;bus.emit=function(n,d){window.__tr.push(performance.now().toFixed(0)+' '+n);return o.apply(this,arguments)};new MutationObserver(()=>window.__tr.push(performance.now().toFixed(0)+' STATE '+document.getElementById('live-talk').dataset.state)).observe(document.getElementById('live-talk'),{attributes:true,attributeFilter:['data-state']})")
    st=lambda:pg.evaluate("({s:document.getElementById('live-talk').dataset.state,mic:document.getElementById('live-talk').dataset.mic,label:document.querySelector('.lt-state').textContent,micTxt:document.querySelector('.lt-mic b').textContent,ripple:+getComputedStyle(document.querySelector('.lt-ripples')).opacity,dots:+getComputedStyle(document.querySelector('.lt-thinkdots')).opacity,stopHidden:document.querySelector('.lt-actions button').hidden})")
    s=st(); print(s)
    check("opens in listening state but does NOT claim the mic is on before recognition starts",s['s']=="listening" and s['mic']=="off" and s['label']!="Listening" and s['ripple']==0,s)
    check("recognition was actually requested",pg.evaluate("window.__listen")>=1)
    pg.evaluate("window.DABSy.bus.emit('voice:listening:start')"); pg.wait_for_timeout(300)
    s=st(); check("mic on -> 'Listening', ripples visible, badge 'Mic on'",s['mic']=="on" and s['label']=="Listening" and s['micTxt']=="Mic on" and s['ripple']>0.9,s)
    pg.screenshot(path="/tmp/lt_listening.png")
    # eyes + body images really loaded
    check("DABSy's own character layers are loaded (body, eyes, bow)",pg.evaluate("Array.from(document.querySelectorAll('.lt-layers img')).every(i=>i.complete&&i.naturalWidth>0)") and pg.locator(".lt-layers img").count()==5)
    check("no generic random circle/ring element remains",pg.locator(".lt-ring").count()==0)
    # heard -> thinking
    pg.evaluate("window.DABSy.bus.emit('voice:heard',{text:'what is newtons second law'});window.DABSy.bus.emit('voice:listening:end')"); pg.wait_for_timeout(400)
    s=st(); print(s)
    check("thinking: distinct state, mic OFF, ripples gone, dots visible",s['s']=="thinking" and s['mic']=="off" and s['micTxt']=="Mic off" and s['ripple']==0 and s['dots']>0.9 and s['label']=="Thinking",s)
    pg.screenshot(path="/tmp/lt_thinking.png")
    # reply appears in subtitle -> mirrored
    pg.evaluate("window.DABSy.app.showSubtitle('Force equals mass times acceleration.')"); pg.wait_for_timeout(300)
    check("reply mirrored into the card while thinking state continues (not abruptly ended)",pg.evaluate("document.querySelector('.lt-said').textContent").startswith("Force equals") and pg.evaluate("document.getElementById('live-talk').hidden")==False)
    # speaking
    pg.evaluate("window.DABSy.bus.emit('voice:speaking:start')"); pg.wait_for_timeout(300)
    s=st(); check("speaking: distinct state, mic OFF, Stop shown",s['s']=="speaking" and s['mic']=="off" and s['label']=="Speaking" and not s['stopHidden'],s)
    pg.evaluate("window.DABSy.bus.emit('voice:boundary')"); pg.wait_for_timeout(30)
    check("character beats on spoken words",pg.evaluate("document.querySelector('.lt-char').classList.contains('beat')"))
    pg.screenshot(path="/tmp/lt_speaking.png")
    # expand
    h0=pg.evaluate("document.getElementById('live-talk').getBoundingClientRect().height")
    pg.click(".lt-icon"); pg.wait_for_timeout(900)
    h1=pg.evaluate("document.getElementById('live-talk').getBoundingClientRect().height")
    check("expands to use more of the screen",h1>h0+200 and pg.evaluate("document.getElementById('live-talk').dataset.size")=="full",(h0,h1))
    check("expanded view shows the conversation",pg.locator(".lt-line").count()>=2,pg.locator(".lt-line").all_inner_texts())
    check("DABSy and controls still visible when expanded",pg.locator(".lt-char").is_visible() and pg.locator(".lt-actions .primary").is_visible() and pg.locator(".lt-icon").is_visible())
    box=pg.evaluate("(()=>{const r=document.getElementById('live-talk').getBoundingClientRect();return [r.top,r.bottom,innerHeight]})()")
    check("expanded card fits the screen",box[0]>=0 and box[1]<=box[2],box)
    pg.screenshot(path="/tmp/lt_full.png")
    # interrupt by tapping the character while speaking
    print("TR",pg.evaluate("window.__tr"));print("PRE",st(),pg.evaluate("window.__stopS"))
    pg.click(".lt-char"); pg.wait_for_timeout(500)
    print("POST",st(),pg.evaluate("[window.__stopS,window.__listen]"))
    check("tapping DABSy while it speaks interrupts and returns to listening",pg.evaluate("window.__stopS")>=1 and st()['s']=="listening" and pg.evaluate("window.__listen")>=2,st())
    pg.click(".lt-icon"); pg.wait_for_timeout(800)
    check("collapses again",pg.evaluate("document.getElementById('live-talk').dataset.size")=="compact")
    pg.click(".lt-actions .primary"); pg.wait_for_timeout(400)
    check("End closes the panel and mic badge resets",pg.evaluate("document.getElementById('live-talk').hidden") and not pg.evaluate("document.body.classList.contains('live-talk')"))
    check("no page errors",not errs,errs[:3])
    b.close()
finally: srv.terminate()
import sys; sys.exit(0 if summary() else 1)
